<!--
 * OAuth2 应用管理页面 — 管理 OAuth2 客户端应用注册信息
 *
 * @path apps\userinfo-web\src\views\oauth2\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * OAuth2 应用管理（列表页）
 * <p>OAuth2 客户端应用的列表页，消费后端契约 OAuth2ApplicationController
 * （src/api/oAuth2Application.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询应用列表，支持创建/编辑/重置密钥/删除等操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import {
  ElButton,
  ElForm,
  ElFormItem,
  ElInput,
  ElInputNumber,
  ElMessage,
  ElMessageBox,
  ElRadioButton,
  ElRadioGroup,
  ElTag,
} from 'element-plus';
import { computed, h, reactive, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { createLogger } from '@YDSZ-core/shared/utils';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import type { OAuth2Application } from '#/api/models';
import {
  create,
  deleteApi,
  getById,
  page,
  resetSecret,
  update,
} from '#/api/oAuth2Application';

defineOptions({ name: 'OAuth2Management' });

const logger = createLogger('userinfo-oauth2');
const { t } = useI18n();

/** OAuth2 应用状态判断 */
function isEnabled(status?: string): boolean {
  return status === 'ENABLED';
}

/** 脱敏展示 clientSecret */
function maskSecret(secret?: string): string {
  if (!secret || secret.length <= 8) return '********';
  return `${secret.slice(0, 4)}****${secret.slice(-4)}`;
}

// ========== VxeTable 配置 ==========
const gridOptions: VxeTableGridOptions<OAuth2Application> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'clientId', title: 'Client ID', width: 200 },
    { field: 'clientName', title: '应用名称', minWidth: 140 },
    {
      field: 'clientType',
      title: '客户端类型',
      width: 100,
      slots: {
        default: ({ row }) => {
          const isConfidential = row.clientType === 'CONFIDENTIAL';
          return h(
            ElTag,
            { type: isConfidential ? 'primary' : 'info', size: 'small' },
            () => (isConfidential ? '机密' : '公开'),
          );
        },
      },
    },
    {
      field: 'redirectUris',
      title: '回调地址',
      minWidth: 180,
      formatter: ({ row }) => {
        const uris = row.redirectUris;
        if (!uris || uris.length === 0) return '-';
        return uris.join(', ');
      },
    },
    {
      field: 'allowedScopes',
      title: '授权范围',
      width: 140,
      formatter: ({ row }) => {
        const scopes = row.allowedScopes;
        if (!scopes || scopes.length === 0) return '-';
        return scopes.join(', ');
      },
    },
    {
      field: 'clientSecret',
      title: '密钥（脱敏）',
      width: 140,
      formatter: ({ row }) => maskSecret(row.clientSecret),
    },
    {
      field: 'status',
      title: '状态',
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            ElTag,
            { type: enable ? 'success' : 'danger', size: 'small' },
            () => (enable ? t('page.enabled') : t('page.disabled')),
          );
        },
      },
    },
    {
      field: 'action',
      title: '操作',
      width: 220,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1 flex-wrap' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) },
              () => t('page.edit'),
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'warning', onClick: () => handleResetSecret(row) },
              () => '重置密钥',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => t('page.delete'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({
          status: formValues?.status || undefined,
          keyword: formValues?.keyword || undefined,
          pageNum: _page?.currentPage,
          pageSize: _page?.pageSize,
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'Input',
        componentProps: { placeholder: '应用名称/Client ID' },
        fieldName: 'keyword',
        label: '关键词',
      },
      {
        component: 'Select',
        componentProps: {
          placeholder: t('page.status'),
          options: [
            { label: '已启用', value: 'ENABLED' },
            { label: '已停用', value: 'DISABLED' },
          ],
        },
        fieldName: 'status',
        label: t('page.status'),
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: t('page.search') },
    resetButtonOptions: { content: t('page.reset') },
  },
});

// ========== 表单弹窗 ==========
const formRef = ref();
const isEdit = ref(false);

interface OAuth2FormState {
  id: string;
  clientId: string;
  clientName: string;
  clientType: string;
  redirectUrisText: string;
  allowedScopesText: string;
  allowedAudiencesText: string;
  description: string;
  sortOrder: number;
}

const formData = reactive<OAuth2FormState>({
  id: '',
  clientId: '',
  clientName: '',
  clientType: 'CONFIDENTIAL',
  redirectUrisText: '',
  allowedScopesText: '',
  allowedAudiencesText: '',
  description: '',
  sortOrder: 0,
});

const rules = {
  clientId: [{ required: true, message: '请输入 Client ID', trigger: 'blur' }],
  clientName: [{ required: true, message: '请输入应用名称', trigger: 'blur' }],
  redirectUrisText: [{ required: true, message: '请输入回调地址（每行一个）', trigger: 'blur' }],
};

const [Modal, modalApi] = useYDSZModal({
  onOpenChange: async (isOpen: boolean) => {
    if (!isOpen) return;
    const data = modalApi.getData<{ record?: OAuth2Application }>();
    if (data?.record?.clientId) {
      isEdit.value = true;
      try {
        const detail = await getById({ id: data.record.clientId });
        Object.assign(formData, {
          id: detail.clientId ?? '',
          clientId: detail.clientId ?? '',
          clientName: detail.clientName ?? '',
          clientType: detail.clientType ?? 'CONFIDENTIAL',
          redirectUrisText: (detail.redirectUris ?? []).join('\n'),
          allowedScopesText: (detail.allowedScopes ?? []).join('\n'),
          allowedAudiencesText: (detail.allowedAudiences ?? []).join('\n'),
          description: detail.description ?? '',
        });
      } catch (error) {
        logger.warn('获取 OAuth2 应用详情失败: {}', error);
      }
    } else {
      isEdit.value = false;
      Object.assign(formData, {
        id: '',
        clientId: '',
        clientName: '',
        clientType: 'CONFIDENTIAL',
        redirectUrisText: '',
        allowedScopesText: '',
        allowedAudiencesText: '',
        description: '',
        sortOrder: 0,
      });
    }
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch (error) {
      logger.warn('表单校验失败: {}', error);
      return;
    }
    modalApi.lock();
    try {
      const parseList = (text: string) =>
        text
          .split('\n')
          .map((s) => s.trim())
          .filter(Boolean);

      const payload: Record<string, unknown> = {
        clientId: formData.clientId,
        clientName: formData.clientName,
        clientType: formData.clientType,
        redirectUris: parseList(formData.redirectUrisText),
        allowedScopes: parseList(formData.allowedScopesText),
        allowedAudiences: parseList(formData.allowedAudiencesText),
        description: formData.description,
        sortOrder: formData.sortOrder,
      };
      if (isEdit.value) {
        await update({ id: formData.id }, payload);
        ElMessage.success('更新成功');
      } else {
        await create(payload);
        ElMessage.success('创建成功');
      }
      modalApi.close();
      gridApi.query();
    } catch (error) {
      logger.warn('保存 OAuth2 应用失败: {}', error);
    } finally {
      modalApi.unlock();
    }
  },
});

const modalTitle = computed(() => (isEdit.value ? '编辑 OAuth2 应用' : '创建 OAuth2 应用'));

function handleAdd() {
  modalApi.setData({});
  modalApi.open();
}

function handleEdit(row: OAuth2Application) {
  modalApi.setData({ record: row });
  modalApi.open();
}

async function handleResetSecret(row: OAuth2Application) {
  if (!row.clientId) return;
  try {
    await ElMessageBox.confirm(
      `确认重置应用 "${row.clientName ?? row.clientId}" 的密钥？旧密钥将立即失效。`,
      '重置密钥',
      { type: 'warning' },
    );
  } catch {
    return;
  }
  try {
    const result = await resetSecret({ id: row.clientId });
    ElMessage.success(`新密钥：${result.clientSecret}（请立即保存）`);
    gridApi.query();
  } catch (error) {
    logger.warn('重置密钥失败: {}', error);
  }
}

async function handleDelete(row: OAuth2Application) {
  if (!row.clientId) return;
  try {
    await ElMessageBox.confirm(
      `确认删除应用 "${row.clientName ?? row.clientId}"？此操作不可恢复。`,
      '确认删除',
      { type: 'warning' },
    );
  } catch {
    return;
  }
  try {
    await deleteApi({ id: row.clientId });
    ElMessage.success(t('page.deleteSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('删除 OAuth2 应用失败: {}', error);
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="OAuth2 应用管理">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">创建应用</ElButton>
      </template>
    </Grid>

    <!-- 创建/编辑弹窗 -->
    <Modal :title="modalTitle">
      <ElForm
        ref="formRef"
        :model="formData"
        :rules="rules"
        label-width="110px"
        label-position="right"
      >
        <ElFormItem label="Client ID" prop="clientId">
          <ElInput v-model="formData.clientId" placeholder="唯一标识，如 my-app-client" :disabled="isEdit" />
        </ElFormItem>
        <ElFormItem label="应用名称" prop="clientName">
          <ElInput v-model="formData.clientName" placeholder="请输入应用名称" />
        </ElFormItem>
        <ElFormItem label="客户端类型">
          <ElRadioGroup v-model="formData.clientType">
            <ElRadioButton value="CONFIDENTIAL">机密</ElRadioButton>
            <ElRadioButton value="PUBLIC">公开</ElRadioButton>
          </ElRadioGroup>
        </ElFormItem>
        <ElFormItem label="回调地址" prop="redirectUrisText">
          <ElInput
            v-model="formData.redirectUrisText"
            type="textarea"
            :rows="3"
            placeholder="每行一个地址，如 https://example.com/callback"
          />
        </ElFormItem>
        <ElFormItem label="授权范围">
          <ElInput
            v-model="formData.allowedScopesText"
            type="textarea"
            :rows="2"
            placeholder="每行一个 scope，如 read:profile"
          />
        </ElFormItem>
        <ElFormItem label="允许受众">
          <ElInput
            v-model="formData.allowedAudiencesText"
            type="textarea"
            :rows="2"
            placeholder="每行一个 audience，如 https://api.example.com"
          />
        </ElFormItem>
        <ElFormItem label="排序">
          <ElInputNumber v-model="formData.sortOrder" :min="0" :max="999" />
        </ElFormItem>
        <ElFormItem label="描述">
          <ElInput
            v-model="formData.description"
            type="textarea"
            :rows="2"
            placeholder="应用描述"
          />
        </ElFormItem>
      </ElForm>
    </Modal>
  </Page>
</template>
